questions.model:
找首个key>x.key的upper_bound，把新来的x插在原有等键之后。得到pos后从i-1递减到pos右移，最后写x。定位比较O(log i)，整段移动仍O(i)，总最坏O(n²)，额外一个记录。

参考实现：
```c
void binaryInsertion(SortRecord a[],int n){for(int i=1;i<n;i++){SortRecord x=a[i];int lo=0,hi=i;while(lo<hi){int mid=lo+(hi-lo)/2;if(a[mid].key<=x.key)lo=mid+1;else hi=mid;}for(int j=i;j>lo;j--)a[j]=a[j-1];a[lo]=x;}}
/* 折半查找首个key>x.key的位置，新记录排在已有等键之后。右移从末项向前，避免覆盖尚未移动的记录。 */
```

取枢轴作<、=、>三路分区，若目标0起始秩k-1在左区递归左，在等区直接返回枢轴，否则右区并保持全局区间秩映射。每次至少排除等区，重复全等一趟结束。随机枢轴期望O(n)、最坏O(n²)，迭代可O(1)额外分区空间，不冒称最坏线性。

参考实现：
```c
int quickSelect(int a[],int n,int k){int left=0,right=n,target=k-1;while(left<right){int pivot=a[left+(right-left)/2],low=left,i=left,high=right;while(i<high){if(a[i]<pivot){int x=a[low];a[low++]=a[i];a[i++]=x;}else if(a[i]>pivot){int x=a[--high];a[high]=a[i];a[i]=x;}else i++;}if(target<low)right=low;else if(target>=high)left=high;else return pivot;}return a[target];}
/* 全局秩target落在[low,high)时答案就是pivot；否则只继续目标所在侧。非空等键段被一次排除，全部相等也能一趟结束，避免重复键使区间不收缩。 */
```

递归统计左右，再升序归并：左key≤右时取左不加；左>右时取右，并加左段尚余项数mid-i。相等不计严格逆序。总O(n log(n+1))时间O(n)缓冲，计数类型容纳n(n-1)/2。若不许改原数组则先复制并计额外空间。

参考实现：
```c
static long long countPart(int a[],int work[],int l,int r){if(r-l<2)return 0;int mid=l+(r-l)/2;long long count=countPart(a,work,l,mid)+countPart(a,work,mid,r);int i=l,j=mid,k=l;while(i<mid&&j<r){if(a[i]<=a[j])work[k++]=a[i++];else{work[k++]=a[j++];count+=(long long)(mid-i);}}while(i<mid)work[k++]=a[i++];while(j<r)work[k++]=a[j++];for(i=l;i<r;i++)a[i]=work[i];return count;}
long long countInversions(int a[],int n,int work[]){return countPart(a,work,0,n);}
```
